<script setup lang="ts">import {onMounted,ref,watch} from 'vue';import {useRoute} from 'vue-router';import http from '../api/http';import PublicState from './PublicState.vue';const route=useRoute(),loading=ref(true),error=ref(''),item=ref<any>(null),schedules=ref<any[]>([]);async function load(){loading.value=true;try{const id=route.params.id;const [department,plan]=await Promise.all([http.get(`/public/departments/${id}`),http.get(`/public/departments/${id}/schedules`,{params:{page:1,pageSize:20}})]);item.value=department.data.data;schedules.value=plan.data.data.records;}catch(e:any){error.value=e.message??'科室不存在或未发布';}finally{loading.value=false;}}onMounted(load);watch(()=>route.params.id,load);</script><template><section class="page"><PublicState :loading="loading" :error="error" :empty="!item"><article class="detail"><h1>{{item.name}}</h1><p>{{item.introduction}}</p><dl><dt>位置</dt><dd>{{item.locationDescription||'待完善'}}</dd><dt>联系电话</dt><dd>{{item.telephone||'待完善'}}</dd><dt>公开医生数</dt><dd>{{item.doctorCount}}</dd></dl><h2>近期出诊</h2><p v-if="!schedules.length">暂无已发布的未来出诊。</p><router-link v-else v-for="schedule in schedules" :key="schedule.id" class="detail" :to="`/booking?departmentId=${route.params.id}&scheduleId=${schedule.id}`">{{schedule.scheduleDate}} {{schedule.sessionName}} · {{schedule.doctorName}} · 剩余 {{schedule.availableQuota}} 号</router-link></article></PublicState></section></template>
